"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

interface TooltipProps {
 content: React.ReactNode;
 children: React.ReactNode;
 position?: "top" | "bottom" | "left" | "right";
 delay?: number;
 className?: string;
}

export function Tooltip({
 content,
 children,
 position = "top",
 delay = 200,
 className,
}: TooltipProps) {
 const [isVisible, setIsVisible] = React.useState(false);
 const timeoutRef = React.useRef<NodeJS.Timeout | null>(null);

 // Cleanup timeout on unmount to prevent memory leak
 React.useEffect(() => {
 return () => {
 if (timeoutRef.current) {
 clearTimeout(timeoutRef.current);
 }
 };
 }, []);

 const showTooltip = () => {
 timeoutRef.current = setTimeout(() => {
 setIsVisible(true);
 }, delay);
 };

 const hideTooltip = () => {
 if (timeoutRef.current) {
 clearTimeout(timeoutRef.current);
 timeoutRef.current = null;
 }
 setIsVisible(false);
 };

 const positionClasses = {
 top: "bottom-full left-1/2 -translate-x-1/2 mb-2",
 bottom: "top-full left-1/2 -translate-x-1/2 mt-2",
 left: "right-full top-1/2 -translate-y-1/2 mr-2",
 right: "left-full top-1/2 -translate-y-1/2 ml-2",
 };

 const arrowClasses = {
 top: "top-full left-1/2 -translate-x-1/2 border-t-stone-800 dark:border-t-neutral-700 border-l-transparent border-r-transparent border-b-transparent",
 bottom: "bottom-full left-1/2 -translate-x-1/2 border-b-stone-800 dark:border-b-neutral-700 border-l-transparent border-r-transparent border-t-transparent",
 left: "left-full top-1/2 -translate-y-1/2 border-l-stone-800 dark:border-l-neutral-700 border-t-transparent border-b-transparent border-r-transparent",
 right: "right-full top-1/2 -translate-y-1/2 border-r-stone-800 dark:border-r-neutral-700 border-t-transparent border-b-transparent border-l-transparent",
 };

 return (
 <div
 className="relative inline-flex"
 onMouseEnter={showTooltip}
 onMouseLeave={hideTooltip}
 onFocus={showTooltip}
 onBlur={hideTooltip}
 >
 {children}
 {isVisible && content && (
 <div
 className={cn(
 "absolute z-50 px-3 py-1.5 text-xs font-medium text-white bg-stone-800 dark:bg-neutral-700 whitespace-nowrap",
 "animate-in fade-in-0 zoom-in-95 duration-150",
 positionClasses[position],
 className
 )}
 role="tooltip"
 >
 {content}
 <div
 className={cn(
 "absolute w-0 h-0 border-[6px]",
 arrowClasses[position]
 )}
 />
 </div>
 )}
 </div>
 );
}

// Simple inline tooltip for help text
interface HelpTooltipProps {
 content: string;
 className?: string;
}

export function HelpTooltip({ content, className }: HelpTooltipProps) {
 return (
 <Tooltip content={content} position="top">
 <svg
 className={cn("w-4 h-4 text-stone-400 dark:text-neutral-500 cursor-help", className)}
 fill="none"
 viewBox="0 0 24 24"
 stroke="currentColor"
 >
 <path
 strokeLinecap="round"
 strokeLinejoin="round"
 strokeWidth={2}
 d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"
 />
 </svg>
 </Tooltip>
 );
}
